SELECT programacionCultivos.codigosistema, infoSemilla.semilla, infoSemilla.variedad, programacionCultivos.factura, programacionCultivos.fechasiembra, programacionCultivos.numeroPlantasSembradas, programacionCultivos.lote, programacionCultivos.cama, (Date()-[programacionCultivos].[fechasiembra]) AS [#dias], programacionCultivos.cantidadAbono0, programacionCultivos.cantidadAbono0, [programacionCultivos].[fechasiembra]+25 AS fecha25Abono, Weekday([fecha25Abono]) AS diaSemana, 3-[diaSemana] AS diasResta, [fecha25Abono]+[diasResta] AS Abono25Mar, infoSemilla.abonoPrimera, [programacionCultivos].[fechasiembra]+50 AS fecha50Abono, Weekday([fecha50Abono]) AS diaSemana50, 3-[diaSemana50] AS diasResta50, [fecha50Abono]+[diasResta50] AS abono50Mar, infoSemilla.abonoSegunda, [programacionCultivos].[fechasiembra]+75 AS fecha75Abono, Weekday([fecha75Abono]) AS diaSemana75, 3-[diaSemana75] AS diasResta75, [fecha75Abono]+[diasResta75] AS abono75Mar, infoSemilla.abonoTercera, [fechasiembra]+15 AS creceMas1, Weekday([creceMas1]) AS diaSemCreMas, (2-[diaSemCreMas])+[creceMas1] AS creceMas15Lun, [fechasiembra]+30 AS creceMas2, Weekday([creceMas2]) AS diaSemCreceMas2, (2-[diaSemCreceMas2])+[creceMas2] AS creceMas30Lun, ([infoSemilla]![abonoTercera]/[infoSemilla]![abonoTercera])+[programacionCultivos]![fechasiembra]+45 AS creceMas3, [fechasiembra]+45 AS produceMas1, Weekday([produceMas1]) AS diaSemProduceMas1, (4-[diaSemProduceMas1])+[produceMas1] AS produceMas50Mier, ([infoSemilla]![abonoTercera]/[infoSemilla]![abonoTercera])+[programacionCultivos]![fechasiembra]+70 AS produceMas2, Weekday([produceMas2]) AS diaSemProduceMas2, (4-[diaSemProduceMas2])+[produceMas2] AS produceMas70Mier, [fechasiembra]+infoSemilla![Aplicacion1] AS saferMix1, Weekday([saferMix1]) AS diaSemSaferMix1, (2-[diaSemSaferMix1])+[saferMix1] AS saferMix0Lun, [fechasiembra]+infoSemilla![Aplicacion1]+60 AS saferMix60dias, Weekday([saferMix60dias]) AS diaSemSaferMix2, (5-[diaSemSaferMix2])+[saferMix60dias] AS saferMix60Juev, (infoSemilla![Aplicacion2]+[fechasiembra])+45 AS sulfoCalcico45, Weekday([sulfoCalcico45]) AS diaSemSulfoCalcico, (5-[diaSemSulfoCalcico])+[sulfoCalcico45] AS sulfoCalcico45Juev, (infoSemilla![Aplicacion2]+[fechasiembra])+44 AS saferSoil, Weekday([bordeles70]) AS diaSemBordeles70, (infoSemilla![Aplicacion2]+[fechasiembra])+70 AS bordeles70, (5-[diaSemBordeles70])+[bordeles70] AS bordeles70Juev, cosecha.fechaCosecha, cosecha.numeroPlantasCosechadas, cosecha.peso, cosecha.remision, cosecha.factura, cosecha.observacion
FROM (infoSemilla INNER JOIN programacionCultivos ON infoSemilla.Id = programacionCultivos.codSemilla) LEFT JOIN cosecha ON programacionCultivos.codigosistema = cosecha.codigosistema
WHERE (((programacionCultivos.fechasiembra)>[fechaInicial]))
ORDER BY programacionCultivos.fechasiembra;

